import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {

  const active_energy_consumption = Number(input?.tsl_wo_work_order_attribute?.active_energy_consumption ?? 0);

  const parameterBillingItemCodeForSubsidy = input?.parametros_de_la_regla?.parameter_billingItem_code_for_subsidy;
  const activeEnergyBillingItems = input.tsl_wo_work_order_attribute.billing_items.active_energy_billing_items;
  const subsidio = activeEnergyBillingItems.find(item => item.legacy_billing_item_id === parameterBillingItemCodeForSubsidy);

   const percentage = parseFloat(input.custom_graduated_pricing_and_unique_percentage.percentage); 

  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;  

  console.log(billingItemCode)

  if (!billingItemCode) {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: "parameter_billingItem_code for rule Madres comunitarias not found"
      }
    }
  }


  // Fuente ÚNICA: arreglo de rangos
  const prices = Array.isArray(input?.custom_graduated_pricing_and_unique_percentage?.prices)
    ? input.custom_graduated_pricing_and_unique_percentage.prices
    : [];

  // Ordena por límite superior ascendente y mapea a {limite, precio}
  const filteredRanges = prices
    .slice()
    .sort(
      (a, b) =>
        Number(a.interval_high ?? 0) -
        Number(b.interval_high ?? 0)
    )
    .map((r) => ({
      limite:
        Number(r.interval_high) === 999999999 ||
        r.interval_high == null
          ? 999999999
          : Number(r.interval_high),
      precio: Number(r.base_price),
    }));

  if (filteredRanges.length === 0) {
    return {
      ...input,
      result: {
        rule_description: 'Rate prices for Madres comunitarias not found',
        status: 'ERROR',
      }
    };
  }

  let costo = 0;

  if (filteredRanges.length > 0) {

    let consumo_restante = active_energy_consumption;
    let limite_anterior = 0;

    for (const rango of filteredRanges) {
      if (consumo_restante <= 0) break; // Si ya cubrimos el consumo, terminamos

      let consumo_rango = 0;

      if (rango.limite !== null && rango.limite !== 999999999) {
        consumo_rango = Math.min(consumo_restante, rango.limite - limite_anterior);
      } else {
        consumo_rango = consumo_restante; // Último rango sin límite
      }

      costo += consumo_rango * rango.precio;
      consumo_restante -= consumo_rango;
      limite_anterior = rango.limite;
    }
  };
  let importeConsumoDescuento = costo * (percentage/100);
  let importeSubidioDescuento = subsidio.billing_item_amount * (percentage/100);

  let totalAmount = (importeConsumoDescuento + importeSubidioDescuento) * (-1);


 if (totalAmount) {
    const billingItems = input.tsl_wo_work_order_attribute.billing_items.active_energy_billing_items;
    const billingItem = billingItems.find(item => item.legacy_billing_item_id === billingItemCode);
    billingItem.billing_item_amount = totalAmount;

    return {
      ...input,
      result: {
          total_amount: totalAmount,
          status: "OK",
          status_description: "Madres comunitarias calculation rule completed"
        }
    };
  } else {
    return {
      ...input,
      result: {
        status: "ERROR",
        status_description: "The amount of the Madres comunitarias rule could not be calculated."
      }
    };
  }
};
